-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Oficinas de Impressão 3D e Robótica' and a.numero = 6
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 6 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 06', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 06 (10 questões discursivas)',
      '/MATERIAIS/RIO_DO_SUL_MAIS_TECH/OFICINAS_IMPRESSAO_3D_ROBOTICA/ATIVIDADES/ATIVIDADE-PRATICA-AULA-06.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Classifique cada peça da caixa em um dos grupos: sensor, controlador, atuador, fonte de energia ou estrutura.', 0.3, 'Placa de microcontrolador: controlador. Sensor ultrassônico: sensor. Motor com driver: atuador. LED: atuador. Bateria: fonte de energia. Chassi impresso em 3D: estrutura.', 'Nota cheia: as seis peças corretas. Metade: quatro ou cinco certas. Zero: três ou menos.'),
      (v_atividade, 1, 2, 'Explique a função do controlador no robô.', 0.3, 'O controlador é o "cérebro" do robô: lê os sinais dos sensores e executa o programa, decidindo o que os atuadores devem fazer.', 'Nota cheia: cita a leitura dos sensores e a execução do programa/decisão sobre os atuadores. Metade: cita só "cérebro" ou só um dos dois. Zero: função errada ou em branco.'),
      (v_atividade, 1, 3, 'Explique o que a fonte de energia e a estrutura (chassi) fazem pelo robô.', 0.4, 'A fonte de energia (baterias) alimenta os componentes do robô; a estrutura (chassi, que pode ser impresso em 3D) sustenta e organiza os componentes.', 'Nota cheia: explica as duas funções. Metade: explica uma. Zero: nenhuma ou trocadas.'),
      (v_atividade, 2, 1, 'Indique o tipo de sensor mais adequado para cada uma das quatro necessidades.', 0.3, '(1) ultrassônico; (2) toque (botão); (3) luz (LDR); (4) infravermelho / de linha.', 'Nota cheia: as quatro corretas. Metade: duas ou três. Zero: uma ou nenhuma.'),
      (v_atividade, 2, 2, 'Explique como o sensor ultrassônico mede a distância.', 0.3, 'O sensor ultrassônico mede a distância pelo tempo de ida e volta do som: emite o som, ele bate no objeto e volta; quanto maior o tempo, maior a distância.', 'Nota cheia: cita o som e o tempo de ida e volta. Metade: cita só um dos dois. Zero: explicação errada.'),
      (v_atividade, 2, 3, 'Explique o que o sensor entrega ao controlador e dê dois exemplos desse sinal.', 0.4, 'O sensor entrega um sinal ao controlador, que pode ser ligado/desligado (por exemplo, botão pressionado ou não) ou um valor (por exemplo, a distância ou a luminosidade).', 'Nota cheia: diz que entrega um sinal e dá dois exemplos coerentes. Metade: diz o sinal com um exemplo, ou dois exemplos sem dizer que é sinal. Zero: sem relação.'),
      (v_atividade, 3, 1, 'Descreva as três etapas do ciclo (o que o sensor, o controlador e o atuador fazem nessa situação).', 0.4, 'O sensor mede a distância até a pessoa; o controlador compara o valor com a regra do programa; o atuador (motor) responde parando.', 'Nota cheia: as três etapas na função certa. Metade: duas certas. Zero: uma ou nenhuma.'),
      (v_atividade, 3, 2, 'Escreva a regra do programa que o controlador usa para decidir parar o motor.', 0.3, 'Se a distância for menor que 1 metro (100 cm), então parar o motor.', 'Nota cheia: condição com a distância e a ação de parar o motor. Metade: só a condição ou só a ação. Zero: regra sem relação com a situação.'),
      (v_atividade, 3, 3, 'Explique por que esse ciclo precisa se repetir muitas vezes por segundo.', 0.3, 'Porque o ambiente muda o tempo todo; repetindo o ciclo muitas vezes por segundo o robô percebe a pessoa a tempo e responde rapidamente.', 'Nota cheia: cita a mudança do ambiente/ou a necessidade de resposta rápida. Metade: só diz que "repete" sem explicar. Zero: sem relação.'),
      (v_atividade, 4, 1, 'Indique o motor mais adequado para as rodas e o mais adequado para a garra.', 0.3, 'Rodas: motor DC. Garra: servomotor.', 'Nota cheia: os dois corretos. Metade: um correto. Zero: ambos errados.'),
      (v_atividade, 4, 2, 'Explique a diferença de funcionamento entre o motor DC e o servomotor.', 0.4, 'O motor DC gira continuamente; o servomotor gira até um ângulo definido e para nele.', 'Nota cheia: explica o giro contínuo e o giro até ângulo definido. Metade: explica só um. Zero: troca as definições.'),
      (v_atividade, 4, 3, 'Explique de que depende a velocidade do motor DC e qual faixa de ângulo costuma ter o servomotor.', 0.3, 'A velocidade do motor DC depende da tensão e do sinal enviado; o servomotor costuma girar de 0° a 180°.', 'Nota cheia: cita tensão e/ou sinal enviado e a faixa de 0° a 180°. Metade: acerta só um. Zero: nenhum.'),
      (v_atividade, 5, 1, 'Explique por que o motor não deve ser ligado direto na placa controladora.', 0.4, 'Porque o motor exige mais corrente do que a placa controladora consegue fornecer; ligado direto, o motor não funciona direito e pode prejudicar a placa.', 'Nota cheia: cita que o motor exige mais corrente que a placa fornece. Metade: diz que "não funciona" sem a causa. Zero: sem relação.'),
      (v_atividade, 5, 2, 'Diga o que é o driver (ponte H) e o que ele faz entre a placa e o motor.', 0.3, 'O driver (ponte H) fica entre a placa e o motor: recebe o comando da placa e entrega ao motor a corrente necessária.', 'Nota cheia: diz onde fica e que fornece corrente/aciona o motor conforme o comando. Metade: diz só um aspecto. Zero: errado.'),
      (v_atividade, 5, 3, 'Indique a outra solução, além do driver, que a aula cita para alimentar o motor.', 0.3, 'Usar uma fonte própria para o motor.', 'Nota cheia: fonte própria (alimentação separada). Zero: outra resposta.'),
      (v_atividade, 6, 1, 'Aponte dois cuidados de segurança que o grupo deve ter ao ligar a bateria.', 0.4, 'Exemplos: não ligar a bateria com fios soltos; conferir a polaridade; ligar a bateria só depois de a montagem estar conferida.', 'Nota cheia: dois cuidados coerentes com a aula. Metade: um. Zero: nenhum coerente.'),
      (v_atividade, 6, 2, 'Explique o que o aluno deve fazer antes de alterar a montagem.', 0.3, 'Desligar a bateria antes de alterar a montagem.', 'Nota cheia: desligar antes de mexer. Metade: diz "ter cuidado" sem desligar. Zero: orienta mexer ligado.'),
      (v_atividade, 6, 3, 'Explique por que é importante conferir a polaridade (positivo e negativo) antes de ligar.', 0.3, 'Porque o positivo e o negativo precisam estar nos terminais certos; ligação invertida pode danificar componentes e comprometer o funcionamento.', 'Nota cheia: cita ligar nos terminais certos e o risco/erro de funcionamento. Metade: cita só um. Zero: sem relação.'),
      (v_atividade, 7, 1, 'Liste três pontos da ligação ou dos componentes que você verificaria.', 0.4, 'Exemplos: se o sensor está ligado à placa conforme o esquema; se o motor e o driver estão ligados corretamente; se a bateria/fonte está ligada e com polaridade certa; se os cabos estão firmes.', 'Nota cheia: três pontos coerentes. Metade: dois. Zero: um ou nenhum.'),
      (v_atividade, 7, 2, 'Diga o que verificar no programa carregado na placa para o motor parar.', 0.3, 'Verificar se o programa de teste foi carregado e se a regra compara a distância do sensor e manda o motor parar quando o obstáculo é detectado.', 'Nota cheia: cita o programa carregado e a regra de parar na detecção. Metade: cita só um. Zero: sem relação.'),
      (v_atividade, 7, 3, 'Explique como você testaria depois da correção e o que registraria.', 0.3, 'Aproximar a mão ou o objeto do sensor, observar se o motor para e registrar o que mudou.', 'Nota cheia: descreve o teste com aproximação e o registro do que mudou. Metade: só o teste ou só o registro. Zero: sem relação.'),
      (v_atividade, 8, 1, 'Descreva, em ordem, os passos para montar e testar o conjunto.', 0.4, 'Identificar cada componente do kit e sua função; ligar o sensor e o motor à placa seguindo o esquema do professor; carregar o programa de teste; observar a resposta do motor.', 'Nota cheia: pelo menos três passos na ordem certa. Metade: dois. Zero: um ou nenhum.'),
      (v_atividade, 8, 2, 'Diga o que deve acontecer com o motor quando a mão se aproxima do sensor.', 0.3, 'O motor liga ou para ao detectar a mão (conforme o programa de teste).', 'Nota cheia: indica que o motor muda de estado (liga ou para) quando o sensor detecta. Metade: resposta vaga. Zero: diz que nada muda ou errado.'),
      (v_atividade, 8, 3, 'Explique o que o grupo deve registrar ao aproximar e afastar a mão ou o objeto.', 0.3, 'O que mudou na resposta do motor ao aproximar a mão ou o objeto (e ao afastar).', 'Nota cheia: registra a resposta do motor em função da aproximação. Metade: registro vago. Zero: sem relação.'),
      (v_atividade, 9, 1, 'Indique os dois sensores necessários para o projeto.', 0.3, 'Sensor de luz (LDR) e sensor de toque (botão).', 'Nota cheia: os dois. Metade: um. Zero: nenhum.'),
      (v_atividade, 9, 2, 'Indique os atuadores necessários e o motor mais adequado para a garra.', 0.4, 'Atuadores: a luz (LED) e o motor da garra; o motor mais adequado para a garra é o servomotor, que gira até um ângulo definido.', 'Nota cheia: luz, motor da garra e servomotor com justificativa. Metade: dois desses. Zero: um ou nenhum.'),
      (v_atividade, 9, 3, 'Explique o papel do controlador nesse projeto.', 0.3, 'O controlador lê os sinais dos sensores, compara com as regras do programa (escuro: acender a luz; botão pressionado: fechar a garra) e comanda os atuadores.', 'Nota cheia: leitura dos sensores, regra e comando dos atuadores. Metade: dois desses. Zero: um ou nenhum.'),
      (v_atividade, 10, 1, 'Descreva o esquema da ligação em palavras, na ordem em que o sinal percorre os componentes.', 0.4, 'Exemplo: o sensor envia o sinal à placa controladora; a placa, pelo programa, envia o comando ao driver; o driver aciona o motor com a energia da bateria.', 'Nota cheia: sensor, controlador, driver e motor na ordem, com a fonte de energia. Metade: ordem correta mas faltando componente, ou ordem trocada. Zero: sem relação com a montagem.'),
      (v_atividade, 10, 2, 'Escreva o relatório curto com as palavras sensor, controlador e atuador e a resposta observada no teste.', 0.3, 'Texto pessoal coerente que usa sensor, controlador e atuador e diz o que o motor fez ao aproximar a mão ou o objeto.', 'Nota cheia: as três palavras no papel certo e a resposta observada. Metade: falta uma palavra ou a resposta observada. Zero: sem relação.'),
      (v_atividade, 10, 3, 'Explique o que o controlador faz com o sinal do sensor.', 0.3, 'O controlador compara o valor do sinal do sensor com uma regra do programa e, conforme o resultado, comanda o atuador.', 'Nota cheia: cita a comparação com a regra e o comando ao atuador. Metade: cita só um. Zero: sem relação.');
end $$;
